function onLoad() {
   if(g_form.getValue('state') != '10'){
	g_form.setReadOnly('u_wbs',true);
	g_form.setReadOnly('u_year',true);
	g_form.setReadOnly('u_total_budget',true);
	g_form.setReadOnly('u_january',true);
	g_form.setReadOnly('u_february',true);
	g_form.setReadOnly('u_march',true);
	g_form.setReadOnly('u_april',true);
	g_form.setReadOnly('u_may',true);
	g_form.setReadOnly('u_june',true);
	g_form.setReadOnly('u_july',true);
	g_form.setReadOnly('u_august',true);
	g_form.setReadOnly('u_september',true);
	g_form.setReadOnly('u_october',true);
	g_form.setReadOnly('u_november',true);
	g_form.setReadOnly('u_december',true);
   }
   else{
	g_form.setReadOnly('u_wbs',false);
	g_form.setReadOnly('u_year',false);
	g_form.setReadOnly('u_total_budget',false);
	g_form.setReadOnly('u_january',false);
	g_form.setReadOnly('u_february',false);
	g_form.setReadOnly('u_march',false);
	g_form.setReadOnly('u_april',false);
	g_form.setReadOnly('u_may',false);
	g_form.setReadOnly('u_june',false);
	g_form.setReadOnly('u_july',false);
	g_form.setReadOnly('u_august',false);
	g_form.setReadOnly('u_september',false);
	g_form.setReadOnly('u_october',false);
	g_form.setReadOnly('u_november',false);
	g_form.setReadOnly('u_december',false);
   }

}
